function PortfolioEffects() {
  useEffect(() => {
    const root = document.documentElement;
    const toggle = document.getElementById('theme-toggle');
    const saved = localStorage.getItem('portfolio-theme');
    const prefersLight = window.matchMedia('(prefers-color-scheme: light)').matches;
    if (saved === 'light' || (!saved && prefersLight)) root.classList.add('light');
    const syncTheme = () => {
      if (!toggle) return;
      const light = root.classList.contains('light');
      toggle.setAttribute('aria-label', light ? 'Switch to dark mode' : 'Switch to light mode');
      toggle.setAttribute('title', light ? 'Switch to dark mode' : 'Switch to light mode');
    };
    syncTheme();
    const toggleTheme = () => { root.classList.toggle('light'); localStorage.setItem('portfolio-theme', root.classList.contains('light') ? 'light' : 'dark'); syncTheme(); };
    toggle?.addEventListener('click', toggleTheme);

    const copyBtn = document.getElementById('copy-email-btn');
    const copyStatus = document.getElementById('copy-status');
    const copyEmail = async () => { try { await navigator.clipboard.writeText('muhammadtahirffaiz@outlook.com'); if(copyStatus) copyStatus.textContent='Copied!'; copyBtn?.classList.add('text-tertiary'); setTimeout(() => { if(copyStatus) copyStatus.textContent='Copy'; copyBtn?.classList.remove('text-tertiary'); }, 2000); } catch { if(copyStatus) copyStatus.textContent='Failed'; } };
    copyBtn?.addEventListener('click', copyEmail);

    const hero = document.getElementById('home');
    let raf=0, active=false, targetX=0,targetY=0,currentX=0,currentY=0;
    const canMove = hero && window.matchMedia('(pointer: fine)').matches && !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const render=()=>{ raf=0; currentX += (targetX-currentX)*0.085; currentY += (targetY-currentY)*0.085; hero.style.setProperty('--cursor-x',`${currentX}px`); hero.style.setProperty('--cursor-y',`${currentY}px`); hero.style.setProperty('--cursor-glow-x',`${currentX}px`); hero.style.setProperty('--cursor-glow-y',`${currentY}px`); if(active && (Math.abs(targetX-currentX)>.15||Math.abs(targetY-currentY)>.15)) raf=requestAnimationFrame(render); };
    const onMove=e=>{ const r=hero.getBoundingClientRect(); targetX=Math.max(0,Math.min(r.width,e.clientX-r.left)); targetY=Math.max(0,Math.min(r.height,e.clientY-r.top)); if(!active){currentX=targetX;currentY=targetY;active=true;} if(!raf)raf=requestAnimationFrame(render); };
    const onLeave=()=>{active=false;targetX=hero.clientWidth*.5;targetY=hero.clientHeight*.32;if(!raf)raf=requestAnimationFrame(render);};
    if(canMove){ const r=hero.getBoundingClientRect(); currentX=targetX=r.width*.5; currentY=targetY=r.height*.32; hero.style.setProperty('--cursor-x',`${currentX}px`);hero.style.setProperty('--cursor-y',`${currentY}px`);hero.style.setProperty('--cursor-glow-x',`${currentX}px`);hero.style.setProperty('--cursor-glow-y',`${currentY}px`); hero.addEventListener('pointermove',onMove,{passive:true}); hero.addEventListener('pointerleave',onLeave,{passive:true}); }

    const header=document.querySelector('header');
    const links=[...document.querySelectorAll('header nav a[data-path]')];
    const sections=[...new Set(links.map(l=>document.getElementById(l.dataset.path)).filter(Boolean))];
    const mobileToggle=document.getElementById('mobile-menu-toggle');
    const mobileMenu=document.getElementById('mobile-nav');
    const setMobileMenu=open=>{ mobileMenu?.classList.toggle('open',open); mobileMenu?.setAttribute('aria-hidden',open?'false':'true'); mobileToggle?.setAttribute('aria-expanded',open?'true':'false'); if(mobileToggle){ const icon=mobileToggle.querySelector('.material-symbols-outlined'); if(icon) icon.textContent=open?'close':'menu'; mobileToggle.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu'); } };
    const toggleMobileMenu=()=>setMobileMenu(!mobileMenu?.classList.contains('open'));
    const setActive=id=>links.forEach(l=>{const a=l.dataset.path===id;l.classList.toggle('nav-active',a);l.setAttribute('aria-current',a?'page':'false'); if(!a)l.removeAttribute('aria-current');});
    const getCurrent=()=>{const marker=window.scrollY+(header?.offsetHeight||80)+90;let current=sections[0];for(const section of sections){if(section.offsetTop<=marker)current=section;else break;}return current?.id||'home';};
    let ticking=false; let scrollLockUntil=0; const onScroll=()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{if(Date.now()>scrollLockUntil)setActive(getCurrent());ticking=false;});};
    const onNav=e=>{e.preventDefault();const id=e.currentTarget.dataset.path;const target=document.getElementById(id);if(!target)return;setActive(id);scrollLockUntil=Date.now()+900;history.replaceState(null,'','#'+id);const y=target.getBoundingClientRect().top+window.scrollY-(header?.offsetHeight||80)-8;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});setMobileMenu(false);};
    links.forEach(l=>l.addEventListener('click',onNav));
    mobileToggle?.addEventListener('click',toggleMobileMenu);
    window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll,{passive:true});
    setActive(location.hash ? location.hash.slice(1) : getCurrent());
    return ()=>{ toggle?.removeEventListener('click',toggleTheme); copyBtn?.removeEventListener('click',copyEmail); if(canMove){hero.removeEventListener('pointermove',onMove);hero.removeEventListener('pointerleave',onLeave);} links.forEach(l=>l.removeEventListener('click',onNav)); mobileToggle?.removeEventListener('click',toggleMobileMenu); window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',onScroll);if(raf)cancelAnimationFrame(raf); };
  },[]);
  return null;
}

